<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request, type Provider } from '../api'
const providers=ref<Provider[]>([]);const health=ref<any>(null);const loading=ref(false);const error=ref('');const notice=ref('')
async function load(){loading.value=true;error.value='';try{[providers.value,health.value]=await Promise.all([request<Provider[]>('/settings/providers'),request<any>('/settings/health')])}catch(e){error.value=e instanceof Error?e.message:'设置加载失败'}finally{loading.value=false}}
async function save(item:Provider){try{if(item.enabled) await request('/settings/providers/'+item.name+'/health-check',{method:'POST'});await request('/settings/providers/'+item.name,{method:'PATCH',body:JSON.stringify({model:item.model,enabled:item.enabled})});notice.value=item.name+' 配置已保存；新任务将使用新配置'}catch(e){error.value=e instanceof Error?e.message:'保存失败'}}
onMounted(load)
</script>
<template><section class="page-view"><div class="page-heading"><div><span class="eyebrow">SYSTEM CONFIGURATION</span><h2>系统设置</h2><p>查看能力健康和 Provider 配置。保存前应执行健康校验。</p></div><button class="button secondary" @click="load" :disabled="loading">刷新健康</button></div><p v-if="error" class="inline-error">{{ error }}</p><p v-if="notice" class="inline-notice">{{ notice }}</p><div class="settings-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">CAPABILITY HEALTH</span><h3>能力健康</h3></div><span class="pill" :class="health?.status==='ok'?'pill-success':'pill-warning'">{{ health?.status||'未知' }}</span></div><div v-if="health" v-for="(value,key) in health" :key="key" class="health-row"><strong>{{ key }}</strong><span>{{ typeof value==='object'?JSON.stringify(value):String(value) }}</span></div><div v-else class="empty-panel">暂无健康数据。</div></section><section class="panel"><span class="eyebrow">PROVIDER CONFIG</span><h3>模型 Provider</h3><div v-for="item in providers" :key="item.name" class="provider-row"><div><strong>{{ item.name }}</strong><small>健康检查通过后再启用默认能力</small></div><input v-model="item.model" :aria-label="item.name+' 模型'"><label class="switch"><input v-model="item.enabled" type="checkbox"><span>启用</span></label><button class="text-button" @click="save(item)">保存</button></div><div v-if="!providers.length" class="empty-panel">暂无 Provider 配置。</div></section></div></section></template>